// Guard: only accept calls carrying the shared token (set CM_TOKEN below and the
// same value in the tool's N8N_TOKEN env var). Empty = check disabled, but then
// anyone who learns the webhook URL can spend your API budget.
const CM_TOKEN = '';

// Model config lives HERE, not in the repo — this is the half n8n owns.
// Stable options (sprawdź w swojej konsoli, na który masz limity):
//   gemini-3.5-flash       — najmocniejszy do zadań agentowych/kodowych  (domyślny)
//   gemini-3.6-flash       — balans szybkość/inteligencja
//   gemini-3.5-flash-lite  — najtańszy, gdy koszt zacznie przeszkadzać
const MODEL = 'gemini-3.5-flash';

const body = $input.first().json.body ?? $input.first().json;
const headers = $input.first().json.headers ?? {};

if (CM_TOKEN && headers['x-cm-token'] !== CM_TOKEN) {
  throw new Error('Brak lub zły X-CM-Token');
}
if (!body || !body.system || !body.schema || !body.input) {
  throw new Error('Payload musi mieć pola: system, schema, input');
}

// The system prompt is folded into `input` rather than sent as a separate field:
// `input` is guaranteed to carry the prompt on this endpoint, so this avoids
// depending on a system-instruction field whose shape we did not verify.
const prompt = body.system
  + '\n\n--- DANE WEJSCIOWE (JSON) ---\n'
  + JSON.stringify(body.input);

// Structured output: the schema is enforced by the API, so the model cannot return
// a shape the tool would reject. Gemini accepts standard JSON Schema here, so the
// repo's schema is passed through unchanged — no dialect translation needed.
return [{
  json: {
    model: MODEL,
    input: prompt,
    response_format: {
      type: 'text',
      mime_type: 'application/json',
      schema: body.schema
    }
  }
}];

// Interactions API: wygenerowany tekst siedzi w kroku o type === "model_output",
// w jego content[] jako {type:"text", text:"..."}. UWAGA: przed nim moze wystapic
// krok "thought", wiec szukamy kroku po typie, nigdy po indeksie. Pole `output_text`
// z przykladow w dokumentacji to akcesor SDK — w surowym REST go NIE MA.
const r = $input.first().json;

// status rozstrzyga niepowodzenie wprost, zamiast zgadywac z bledu parsowania
const status = r.status || (r.interaction && r.interaction.status) || null;
if (status && status !== 'completed') {
  throw new Error('Gemini nie ukonczylo generowania (status=' + status + '). '
    + 'incomplete/budget_exceeded = odpowiedz ucieta; failed = blad po stronie modelu. '
    + 'Zrzut: ' + JSON.stringify(r).slice(0, 500));
}

function extractText(obj) {
  // 1) gdyby jakas warstwa jednak podala akcesor SDK
  if (typeof obj.output_text === 'string' && obj.output_text) return obj.output_text;

  // 2) wlasciwa sciezka REST: steps[] -> model_output -> content[] -> text
  const steps = obj.steps || (obj.interaction && obj.interaction.steps) || [];
  const parts = [];
  for (const s of steps) {
    if (!s || s.type !== 'model_output') continue;
    for (const c of (s.content || [])) {
      if (c && c.type === 'text' && typeof c.text === 'string') parts.push(c.text);
    }
  }
  if (parts.length) return parts.join('');

  // 3) stary kształt generateContent — na wypadek przelaczenia endpointu
  const cand = (obj.candidates || [])[0];
  if (cand) {
    const p = (((cand.content || {}).parts) || [])
      .map(function (x) { return x && x.text; }).filter(Boolean);
    if (p.length) return p.join('');
  }
  return null;
}

const text = extractText(r);
if (!text) {
  // Diagnostyka od razu w komunikacie, zeby nie zgadywac przy nastepnym bledzie
  throw new Error('Nie znalazlem tekstu w odpowiedzi Gemini. '
    + 'Pola najwyzszego poziomu: [' + Object.keys(r).join(', ') + ']. '
    + 'Typy krokow: [' + ((r.steps || []).map(function (s) { return s && s.type; })
        .join(', ') || 'brak steps') + ']. '
    + 'Fragment: ' + JSON.stringify(r).slice(0, 300));
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Tekst modelu nie jest poprawnym JSON (status=' + status + '). '
    + 'Jesli to proza, a nie JSON — response_format zostal zignorowany. '
    + 'Poczatek: ' + String(text).slice(0, 300));
}

return [{ json: parsed }];
